changeSet.sql:
UPDATE contract_templates
SET content = REPLACE(content, 'Adresse : {{owner.email}}', 'Adresse email : {{owner.email}}')
WHERE content LIKE '%Adresse : {{owner.email}}%';

rollback.sql:
UPDATE contract_templates
SET content = REPLACE(content, 'Adresse email : {{owner.email}}', 'Adresse : {{owner.email}}')
WHERE content LIKE '%Adresse email : {{owner.email}}%';
